CREATE TEMP VIEW storage_source_projects AS SELECT id,name,CASE WHEN substr(path,1,8)='\\?\UNC\' THEN '\\'||substr(path,9) WHEN substr(path,1,4)='\\?\' THEN substr(path,5) ELSE path END AS path,created_at,position FROM legacy.managed_projects;

CREATE TEMP TABLE storage_project_map AS
SELECT source.id AS old_id, COALESCE(target.id,source.id) AS new_id
FROM storage_source_projects source LEFT JOIN main.managed_projects target ON target.path=source.path;
INSERT INTO main.managed_projects
SELECT source.id,source.name,source.path,source.created_at,
       (SELECT COALESCE(MAX(position)+1,0) FROM main.managed_projects)+source.position
FROM storage_source_projects source WHERE true ON CONFLICT(path) DO NOTHING;
CREATE TEMP TABLE storage_import_guard (ok INTEGER CHECK(ok=1));
INSERT INTO storage_import_guard
SELECT 0 FROM legacy.managed_tasks source JOIN main.managed_tasks target ON target.id=source.id
WHERE source.provider<>target.provider OR source.session_id IS NOT target.session_id;
INSERT INTO main.managed_tasks
SELECT source.id, mapping.new_id, source.title, source.cwd, source.provider, source.session_id,
       source.updated_at, source.pinned, source.archived, source.status
FROM legacy.managed_tasks source LEFT JOIN storage_project_map mapping ON mapping.old_id=source.project_id
WHERE NOT EXISTS (SELECT 1 FROM main.managed_tasks target WHERE target.id=source.id
   OR (source.session_id IS NOT NULL AND target.provider=source.provider AND target.session_id=source.session_id));
INSERT OR IGNORE INTO main.managed_catalog_migration SELECT * FROM legacy.managed_catalog_migration;
DROP TABLE storage_project_map;
DROP TABLE storage_import_guard;

DROP VIEW storage_source_projects;
